    @PostConstruct
    protected void init() {
        Map<String, Object> tmpMap = new HashMap<>();
        tmpMap.put("tender.procuringEntity._id", 1);
        tmpMap.put("tender.procuringEntity.group._id", 1);
        tmpMap.put("tender.procuringEntity.department._id", 1);
