                append(awardCriteriaDetails).
                append(submissionMethod).
                append(submissionMethodDetails).
                append(tenderPeriod).
                append(enquiryPeriod).
                append(hasEnquiries).
                append(eligibilityCriteria).
                append(awardPeriod).
