        tmpMap.put("tender.items.deliveryLocation._id", 1);
        tmpMap.put("tender.procurementMethodDetails", 1);
        tmpMap.put("tender.contrMethod", 1);
        tmpMap.put("tender.value.amount", 1);
        tmpMap.put("awards.value.amount", 1);
