public interface ExcelChart {
    Workbook createWorkbook();

    void configureSeriesTitle(List<String> seriesTitle);
}

public class ExcelChartDefault implements ExcelChart {
    private final ChartType type;

    private final String title;

    private final List<?> categories;

    private final List<List<? extends Number>> values;

    private final Workbook workbook;

    private final List<String> seriesTitle;

    private static final int COLUMNWIDTH = 3500;

    public ExcelChartDefault(final String title, final ChartType type, final List<?> categories,
            final List<List<? extends Number>> values) {
        for (List<? extends Number> value : values) {
            if (categories.size() != value.size()) {
                throw new IllegalArgumentException("categories and value size should match!");
            }
        }

        this.title = title;
        this.type = type;
        this.categories = categories;
        this.values = values;
        this.workbook = new XSSFWorkbook();
        this.seriesTitle = new ArrayList<>();
    }

    @Override
    public Workbook createWorkbook() {
        final ExcelChartSheet excelChartSheet = new ExcelChartSheetDefault(workbook, type.toString());
        final Chart chart = excelChartSheet.createChartAndLegend();

        addCategories(excelChartSheet);
        addValues(excelChartSheet);

        final CustomChartDataFactory customChartDataFactory = new CustomChartDataFactoryDefault();
        final CustomChartData chartData = customChartDataFactory.createChartData(type, title);

        final ChartDataSource<?> categoryDataSource = excelChartSheet.getCategoryChartDataSource();
        final List<ChartDataSource<Number>> valuesDataSource = excelChartSheet.getValuesChartDataSource();
        for (int i = 0; i < valuesDataSource.size(); i++) {
            final ChartDataSource<Number> valueDataSource = valuesDataSource.get(i);
            if (seriesTitle.isEmpty()) {
                chartData.addSeries(categoryDataSource, valueDataSource);
            } else {
                chartData.addSeries(seriesTitle.get(i), categoryDataSource, valueDataSource);
            }
        }

        // we don't have any axis for a pie chart
        if (type.equals(ChartType.pie)) {
            chart.plot(chartData);
        } else {
            // Use a category axis for the bottom axis.
            final ChartAxis bottomAxis = chart.getChartAxisFactory().createCategoryAxis(AxisPosition.BOTTOM);
            final ValueAxis leftAxis = chart.getChartAxisFactory().createValueAxis(AxisPosition.LEFT);
            leftAxis.setCrosses(AxisCrosses.AUTO_ZERO);

            chart.plot(chartData, bottomAxis, leftAxis);
        }

        return workbook;
    }

    @Override
    public void configureSeriesTitle(final List<String> seriesTitle) {
        if (values.size() != seriesTitle.size()) {
            throw new IllegalArgumentException("seriesTitle and values size should match!");
        }
        this.seriesTitle.addAll(seriesTitle);
    }

    /**
     * Add a row with the categories.
     */
    private void addCategories(final ExcelChartSheet excelChartSheet) {
        final Row row = excelChartSheet.createRow();
        if (categories.isEmpty()) {
            excelChartSheet.writeCell("No data", row, 0);
            return;
        }

        int coll = 0;
        for (Object category : categories) {
            excelChartSheet.writeCell(category, row, coll);
            excelChartSheet.setColumnWidth(coll, COLUMNWIDTH);
            coll++;
        }
    }

    /**
     * Add one or multiple rows with the values.
     */
    private void addValues(final ExcelChartSheet excelChartSheet) {
        if (values.isEmpty()) {
            final Row row = excelChartSheet.createRow();
            excelChartSheet.writeCell(0, row, 0);
            return;
        }

        for (List<? extends Number> value : values) {
            final Row row = excelChartSheet.createRow();
            int coll = 0;
            for (Number val : value) {
                excelChartSheet.writeCell(val, row, coll++);
            }
        }
    }
}

public abstract class GenericOCDSController {

    private static final int LAST_MONTH_ZERO = 11;
    public static final int BIGDECIMAL_SCALE = 15;
    public static final int DAY_MS = 86400000;

    public static final BigDecimal ONE_HUNDRED = new BigDecimal(100);


    protected Map<String, Object> filterProjectMap;

    protected final Logger logger = LoggerFactory.getLogger(GenericOCDSController.class);

    @Autowired
    protected MongoTemplate mongoTemplate;

    /**
     * Gets the date of the first day of the year (01.01.year)
     *
     * @param year
     * @return
     */
    protected Date getStartDate(final int year) {
        Calendar cal = Calendar.getInstance();
        cal.set(Calendar.YEAR, year);
        cal.set(Calendar.DAY_OF_YEAR, 1);
        Date start = cal.getTime();
        return start;
    }

    /**
     * This is used to build the start date filter query when a monthly filter is used.
     *
     * @param year
     * @param month
     * @return
     */
    protected Date getMonthStartDate(final int year, final int month) {
        Calendar cal = Calendar.getInstance();
        cal.set(Calendar.YEAR, year);
        cal.set(Calendar.MONTH, month - 1);
        cal.set(Calendar.DAY_OF_MONTH, 1);
        Date start = cal.getTime();
        return start;
    }

    /**
     * This is used to build the end date filter query when a monthly filter is used.
     *
     * @param year
     * @param month
     * @return
     */
    protected Date getMonthEndDate(final int year, final int month) {
        Calendar cal = Calendar.getInstance();
        cal.set(Calendar.YEAR, year);
        cal.set(Calendar.MONTH, month - 1);
        cal.set(Calendar.DAY_OF_MONTH, cal.getActualMaximum(Calendar.DAY_OF_MONTH));
        Date end = cal.getTime();
        return end;
    }


    /**
     * Gets the date of the last date of the year (31.12.year)
     *
     * @param year
     * @return
     */
    protected Date getEndDate(final int year) {
        Calendar cal = Calendar.getInstance();
        cal.set(Calendar.YEAR, year);
        cal.set(Calendar.MONTH, LAST_MONTH_ZERO);
        cal.set(Calendar.DAY_OF_MONTH, cal.getActualMaximum(Calendar.DAY_OF_MONTH));
        Date end = cal.getTime();
        return end;
    }

    protected String ref(String field) {
        return "$" + field;
    }


    /**
     * Appends the procuring bid type id for this filter, this will fitler based
     * on tender.items.classification._id
     *
     * @param filter
     * @return the {@link Criteria} for this filter
     */
    protected Criteria getBidTypeIdFilterCriteria(final DefaultFilterPagingRequest filter) {
        return createFilterCriteria("tender.items.classification._id", filter.getBidTypeId(), filter);
    }

    /**
     * Adds monthly projection operation, when needed, if the
     * {@link YearFilterPagingRequest#getMonthly()}
     *
     * @param filter
     * @param project
     * @param field
     */
    protected void addYearlyMonthlyProjection(YearFilterPagingRequest filter, DBObject project, String field) {
        project.put("year", new BasicDBObject("$year", field));
        if (filter.getMonthly()) {
            project.put(("month"), new BasicDBObject("$month", field));
        }
    }

    protected CustomSortingOperation getSortByYearMonth(YearFilterPagingRequest filter) {
        DBObject sort = new BasicDBObject();
        if (filter.getMonthly()) {
            sort.put("_id.year", 1);
            sort.put("_id.month", 1);
        } else {
            sort.put("year", 1);
        }
        return new CustomSortingOperation(sort);
    }

    /**
     * Similar to {@link #getSortByYearMonth(YearFilterPagingRequest)} but it can be used
     * if additional grouping elements are present, besides month and year
     *
     * @param filter
     * @return
     */
    protected CustomSortingOperation getSortByYearMonthWhenOtherGroups(YearFilterPagingRequest filter,
                                                                       String... otherSort) {
        DBObject sort = new BasicDBObject();
        if (filter.getMonthly()) {
            sort.put("_id.year", 1);
            sort.put("_id.month", 1);
        } else {
            sort.put("_id.year", 1);
        }
        if (otherSort != null) {
            Arrays.asList(otherSort).forEach(s -> sort.put(s, 1));
        }
        return new CustomSortingOperation(sort);
    }


    protected void addYearlyMonthlyReferenceToGroup(YearFilterPagingRequest filter, DBObject group) {
        if (filter.getMonthly()) {
            group.put(Fields.UNDERSCORE_ID, new BasicDBObject("year", "$year").append("month", "$month"));
        } else {
            group.put(Fields.UNDERSCORE_ID, "$year");
        }
    }

    /**
     * Returns the grouping fields based on the {@link YearFilterPagingRequest#getMonthly()} setting
     *
     * @param filter
     * @return
     */
    protected String[] getYearlyMonthlyGroupingFields(YearFilterPagingRequest filter) {
        if (filter.getMonthly()) {
            return new String[]{"$year", "$month"};
        } else {
            return new String[]{"$year"};
        }
    }

    /**
     * @see #getYearlyMonthlyGroupingFields(YearFilterPagingRequest)
     *
     * @param filter
     * @param extraGroups adds extra groups
     * @return
