        Tender rhs = ((Tender) other);
        return new EqualsBuilder().
                append(id, rhs.id).
                append(title, rhs.title).
                append(description, rhs.description).
                append(status, rhs.status).
                append(items, rhs.items).
                append(minValue, rhs.minValue).
