        }

        return new Criteria();
    }

    protected Criteria getNotProcuringEntityIdCriteria(final DefaultFilterPagingRequest filter) {
        return createNotFilterCriteria("tender.procuringEntity._id", filter.getNotProcuringEntityId(), filter);
    }


    /**
