    protected Criteria getYearFilterCriteria(final YearFilterPagingRequest filter, final String dateProperty) {
        Criteria[] yearCriteria = null;
        Criteria criteria = new Criteria();

        if (filter.getYear() == null) {
            yearCriteria = new Criteria[1];
            yearCriteria[0] = new Criteria();
        } else {
            yearCriteria = new Criteria[filter.getYear().size()];
            Integer[] yearArray = filter.getYear().toArray(new Integer[0]);
            for (int i = 0; i < yearArray.length; i++) {
                yearCriteria[i] = where(dateProperty).gte(getStartDate(yearArray[i]))
                        .lte(getEndDate(yearArray[i]));
            }
            criteria = criteria.orOperator(yearCriteria);

            if (filter.getMonth() != null && filter.getYear().size() == 1) {
                Integer[] monthArray = filter.getMonth().toArray(new Integer[0]);
                criteria = new Criteria(); //we reset the criteria because we use only one year
                Criteria[] monthCriteria = new Criteria[filter.getMonth().size()];
                for (int i = 0; i < monthArray.length; i++) {
                    monthCriteria[i] = where(dateProperty).gte(getMonthStartDate(yearArray[0],
                            monthArray[i]))
                            .lte(getMonthEndDate(yearArray[0],
                                    monthArray[i]));
                }
                criteria = criteria.orOperator(monthCriteria);
            }
        }

//        logger.info("Criteria=" + criteria.getCriteriaObject());

        return criteria;
    }

    /**
     * Appends the bid selection method to the filter, this will filter based on
     * tender.procurementMethodDetails. It accepts multiple elements
     *
     * @param filter
     * @return the {@link Criteria} for this filter
     */
    protected Criteria getBidSelectionMethod(final DefaultFilterPagingRequest filter) {
        return createFilterCriteria("tender.procurementMethodDetails", filter.getBidSelectionMethod(), filter);
    }

    protected Criteria getNotBidSelectionMethod(final DefaultFilterPagingRequest filter) {
        return createNotFilterCriteria("tender.procurementMethodDetails", filter.getNotBidSelectionMethod(), filter);
    }


    protected Criteria getDefaultFilterCriteria(final DefaultFilterPagingRequest filter) {
        return new Criteria().andOperator(
                getBidTypeIdFilterCriteria(filter),
                getNotBidTypeIdFilterCriteria(filter),
                getProcuringEntityIdCriteria(filter),
                getNotProcuringEntityIdCriteria(filter),
                getProcuringEntityCityIdCriteria(filter),
                getProcuringEntityGroupIdCriteria(filter),
                getProcuringEntityDepartmentIdCriteria(filter),
                getBidSelectionMethod(filter),
                getContrMethodFilterCriteria(filter),
                getSupplierIdCriteria(filter),
                getProcurementMethodCriteria(filter),
                getByTenderDeliveryLocationIdentifier(filter),
                getByBidPlanLocationIdentifier(filter),
                getByTenderAmountIntervalCriteria(filter),
                getByAwardAmountIntervalCriteria(filter),
                getFlaggedCriteria(filter),
                getElectronicSubmissionCriteria(filter));
    }

    protected Criteria getYearDefaultFilterCriteria(final YearFilterPagingRequest filter, final String dateProperty) {
        return new Criteria().andOperator(
                getBidTypeIdFilterCriteria(filter),
                getNotBidTypeIdFilterCriteria(filter),
                getProcuringEntityIdCriteria(filter),
                getNotProcuringEntityIdCriteria(filter),
                getProcuringEntityCityIdCriteria(filter),
                getProcuringEntityGroupIdCriteria(filter),
                getProcuringEntityDepartmentIdCriteria(filter),
                getBidSelectionMethod(filter),
                getNotBidSelectionMethod(filter),
                getContrMethodFilterCriteria(filter),
                getSupplierIdCriteria(filter),
                getProcurementMethodCriteria(filter),
                getByTenderDeliveryLocationIdentifier(filter),
                getByBidPlanLocationIdentifier(filter),
                getByTenderAmountIntervalCriteria(filter),
                getByAwardAmountIntervalCriteria(filter),
                getElectronicSubmissionCriteria(filter),
                getFlaggedCriteria(filter),
                getYearFilterCriteria(filter, dateProperty));
    }

    protected MatchOperation getMatchDefaultFilterOperation(final DefaultFilterPagingRequest filter) {
        return match(getDefaultFilterCriteria(filter));
    }

    /**
     * Creates a groupby expression that takes into account the filter. It will
     * only use one of the filter options as groupby and ignores the rest.
     *
     * @param filter
     * @param existingGroupBy
     * @return
     */
    protected GroupOperation getTopXFilterOperation(final GroupingFilterPagingRequest filter,
                                                    final String... existingGroupBy) {
        List<String> groupBy = new ArrayList<>();
        if (filter.getGroupByCategory() == null) {
            groupBy.addAll(Arrays.asList(existingGroupBy));
        }

        if (filter.getGroupByCategory() != null) {
            groupBy.add(getGroupByCategory(filter));
        }

        return group(groupBy.toArray(new String[0]));
    }

    private String getGroupByCategory(final GroupingFilterPagingRequest filter) {
        if ("bidSelectionMethod".equals(filter.getGroupByCategory())) {
            return "tender.procurementMethodDetails".replace(".", "");
        } else if ("bidTypeId".equals(filter.getGroupByCategory())) {
            return "tender.items.classification._id".replace(".", "");
        } else if ("procuringEntityId".equals(filter.getGroupByCategory())) {
            return "tender.procuringEntity._id".replace(".", "");
        }
        return null;
    }

}

public class YearFilterPagingRequest extends DefaultFilterPagingRequest {

    @ApiModelProperty(value = "This parameter will filter the content based on year. " + "The minimum year allowed is "
            + MIN_REQ_YEAR + " and the maximum allowed is " + MAX_REQ_YEAR
            + ".It will check if the startDate and endDate are within the year range. "
            + "To check which fields are used to read start/endDate from, have a look at each endpoint definition.")
    @EachRange(min = MIN_REQ_YEAR, max = MAX_REQ_YEAR)
    protected TreeSet<Integer> year;

    @ApiModelProperty(value = "This parameter will filter the content based on month. "
            + "The minimum month allowed is "
            + MIN_MONTH + " and the maximum allowed is " + MAX_MONTH
            + "This parameter does nothing if used without the year parameter, as filtering and aggregating by month "
            + "makes no sense without filtering by year. This parameter is also ignored when using multiple year "
            + "parameters, so it only works if and only if the year parameter has one value.")
    @EachRange(min = MIN_MONTH, max = MAX_MONTH)
    protected TreeSet<Integer> month;
    @ApiModelProperty(value = "When true, this parameter will add an extra layer of monthly grouping of all results."
            + " The default is false")
    private Boolean monthly = false;

    public Boolean getMonthly() {
        return monthly;
    }

    public void setMonthly(Boolean monthly) {
        this.monthly = monthly;
    }

    /**
     *
     */
    public YearFilterPagingRequest() {
        super();
    }

    public TreeSet<Integer> getYear() {
        return year;
    }

    public void setYear(final TreeSet<Integer> year) {
        this.year = year;
    }

    public TreeSet<Integer> getMonth() {
        return month;
    }

    public void setMonth(TreeSet<Integer> month) {
        this.month = month;
    }
}

@Service
public class TranslationService {

    private static final String TRANSLATION_PKG_NAME = "public.languages";

    protected static Logger logger = Logger.getLogger(TranslationService.class);


    @Autowired
    private ObjectMapper objectMapper;

    private Map<String, Map<String, String>> translations = new ConcurrentHashMap<>();

    /**
     * Loads all translation files for the given language in the hashmap.
     *
     * @param language
     */
    private void ensureLanguageLoaded(String language) {
        Assert.notNull(language, "Language must not be null!");
        Assert.isTrue(language.matches("^[a-z]{2}_[A-Z]{2}$"),
                "Language string must comply with RFC5646 standard!");

        if (translations.containsKey(language)) {
            return;
        }
        Set<String> fileNames = getAllTranslationFileNamesForLanguage(language);
        Assert.notEmpty(fileNames, "No translations found for language " + language);

        fileNames.forEach(file ->
                loadLanguageFromTranslationFile(language, file));

        logger.info("Loaded translations for language " + language + " from the following files " + fileNames);
    }

    /**
     * Returns all the translation files for a specific language, sorted naturally by file name
     * The trnaslation files have to start with @param language and end with ".json"
     *
     * @param language
     * @return
     */
    private Set<String> getAllTranslationFileNamesForLanguage(String language) {
        return new TreeSet<String>(new Reflections(TRANSLATION_PKG_NAME, new ResourcesScanner()).
                getResources(Pattern.compile(language + "(.*).json")));
    }

    /**
     * Loads all translation keys from the given file. If the keys already exist, they will be overwritten.
     *
     * @param language
     * @param translationFileName
     */
    private void loadLanguageFromTranslationFile(String language, String translationFileName) {
        try {
            InputStream stream = this.getClass().getResourceAsStream("/" + translationFileName);
            Map<String, String> map = objectMapper.readValue(stream, ConcurrentHashMap.class);
            if (translations.containsKey(language)) {
                translations.get(language).putAll(map);
            } else {
                translations.put(language, map);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Returns the translation registered for the given language and key.
     * The language uses RFC5646
     *
     * @param language
     * @param key
     * @return
     */
    public String getValue(String language, String key) {
        Assert.notNull(key, "Key must not be null!");
        ensureLanguageLoaded(language);
        return translations.get(language).get(key);
    }

    /**
     * Returns the entire map of key-value translations for given language
     *
     * @param language
     * @return
     */
    public Map<String, String> getAllTranslationsForLanguage(String language) {
        ensureLanguageLoaded(language);
        return translations.get(language);
    }

}

