@JsonPropertyOrder({
        "date",
        "changes",
        "rationale"
})
public class Amendment {

    /**
     * Amendment Date
     * <p>
     * The data of this amendment.
     *
     */

    @JsonProperty("date")
    @Merge(MergeStrategy.overwrite)
    private Date date;

    /**
     * Amended fields
     * <p>
     * Comma-seperated list of affected fields.
     *
     */
    @JsonProperty("changes")
    @Merge(MergeStrategy.ocdsVersion)
    private List<Change> changes = new ArrayList<Change>();

    /**
     * An explanation for the amendment.
     *
     */
    @JsonProperty("rationale")
    @Merge(MergeStrategy.ocdsVersion)
    private String rationale;

    /**
     * Amendment Date
     * <p>
     * The data of this amendment.
     *
     * @return
     *     The date
     */
    @JsonProperty("date")
    public Date getDate() {
        return date;
    }

    /**
     * Amendment Date
     * <p>
     * The data of this amendment.
     *
     * @param date
     *     The date
     */
    @JsonProperty("date")
    public void setDate(final Date date) {
        this.date = date;
    }

    /**
     * Amended fields
     * <p>
     * Comma-seperated list of affected fields.
     *
     * @return
     *     The changes
     */
    @JsonProperty("changes")
    public List<Change> getChanges() {
        return changes;
    }

    /**
     * Amended fields
     * <p>
     * Comma-seperated list of affected fields.
     *
     * @param changes
     *     The changes
     */
    @JsonProperty("changes")
    public void setChanges(final List<Change> changes) {
        this.changes = changes;
    }

    /**
     * An explanation for the amendment.
     *
     * @return
     *     The rationale
     */
    @JsonProperty("rationale")
    public String getRationale() {
        return rationale;
    }

    /**
     * An explanation for the amendment.
     *
     * @param rationale
     *     The rationale
     */
    @JsonProperty("rationale")
    public void setRationale(final String rationale) {
        this.rationale = rationale;
    }

    @Override
    public String toString() {
        return ToStringBuilder.reflectionToString(this);
    }

    @Override
    public int hashCode() {
        return new HashCodeBuilder().
                append(date).
                append(changes).
                append(rationale).
                toHashCode();
    }

    @Override
    public boolean equals(final Object other) {
        if (other == this) {
            return true;
        }
        if (!(other instanceof Amendment)) {
            return false;
        }
        Amendment rhs = ((Amendment) other);
        return new EqualsBuilder().
                append(date, rhs.date).
                append(changes, rhs.changes).
                append(rationale, rhs.rationale).
                isEquals();
    }

}

