    protected DBObject groupSumBoolean(String property, Boolean value) {
        return new BasicDBObject("$sum", new BasicDBObject("$cond",
                Arrays.asList(new BasicDBObject("$eq", Arrays.asList(ref(property), value)), 1, 0)));
