@Component
public class ReleaseFlagI077Processor extends AbstractFlaggedReleaseFlagProcessor {

    private static final Integer INTERVAL_DAYS = 365;
    private static final Integer MAX_AWARDS = 3;

    private ConcurrentHashMap<String, FrequentSuppliersTimeIntervalController.FrequentSuppliersResponse>
            frequentSuppliersMap;

    private Date now;
    private Double nowDouble;

    @Autowired
    private FrequentSuppliersTimeIntervalController frequentSuppliersTimeIntervalController;

    @Override
    protected void setFlag(Flag flag, FlaggedRelease flaggable) {
        flaggable.getFlags().setI077(flag);
    }

    protected Integer getInterval(Date awardDate) {
        return new Double(Math.ceil((nowDouble - awardDate.getTime())
                / GenericOCDSController.DAY_MS / INTERVAL_DAYS)).intValue();
    }

    @Override
    protected Boolean calculateFlag(FlaggedRelease flaggable, StringBuffer rationale) {
        return flaggable.getAwards().stream().filter(award -> award.getSuppliers().stream().anyMatch(supplier ->
                flaggable.getTender() != null && flaggable.getTender().getProcuringEntity() != null
                        && supplier != null
                        && frequentSuppliersMap.containsKey(FrequentSuppliersTimeIntervalController.
                        getFrequentSuppliersResponseKey(flaggable.getTender().getProcuringEntity().getId(),
                                supplier.getId(), getInterval(award.getDate()))
                ))
        ).map(award -> rationale
                .append("Award ").append(award.getId()).append(" flagged; "))
                .count() > 0;
    }

    /**
     * Refreshes the internal awards map used to quicksearch after award ids. This needs to be triggered
     * before each flagging process actually starts
     */
    @Override
    public void reInitialize() {
        now = new Date();
        nowDouble = new Double(now.getTime());
        List<FrequentSuppliersTimeIntervalController.FrequentSuppliersResponse> frequentSuppliersTimeInterval
                = frequentSuppliersTimeIntervalController.frequentSuppliersTimeInterval(getIntervalDays(),
                getMaxAwards(), now);

        frequentSuppliersMap = new ConcurrentHashMap<>();

        frequentSuppliersTimeInterval.
                forEach(response -> frequentSuppliersMap.put(
                        FrequentSuppliersTimeIntervalController.getFrequentSuppliersResponseKey(response), response));
    }

    protected Integer getMaxAwards() {
        return MAX_AWARDS;
    }

    protected Integer getIntervalDays() {
        return INTERVAL_DAYS;
    }

    @PostConstruct
    @Override
    protected void setPredicates() {
        preconditionsPredicates = Collections.synchronizedList(
                Arrays.asList(FlaggedReleasePredicates.ACTIVE_AWARD_WITH_DATE,
                        FlaggedReleasePredicates.OPEN_PROCUREMENT_METHOD
                                .or(FlaggedReleasePredicates.SELECTIVE_PROCUREMENT_METHOD)));
    }


    @Override
    protected Set<FlagType> flagTypes() {
        return new HashSet<FlagType>(Arrays.asList(FlagType.RIGGING));
    }
}

@Component
public class ReleaseFlagI085Processor extends AbstractFlaggedReleaseFlagProcessor {

    @PostConstruct
    @Override
    protected void setPredicates() {
        preconditionsPredicates = Collections.synchronizedList(Arrays.asList(
                FlaggedReleasePredicates.ACTIVE_AWARD,
                FlaggedReleasePredicates.ELECTRONIC_SUBMISSION
        ));
    }


    @Override
    protected void setFlag(Flag flag, FlaggedRelease flaggable) {
        flaggable.getFlags().setI085(flag);
    }

    @Override
    protected Set<FlagType> flagTypes() {
        return new HashSet<FlagType>(Arrays.asList(FlagType.FRAUD, FlagType.COLLUSION));
    }

    @Override
    protected Boolean calculateFlag(FlaggedRelease flaggable, StringBuffer rationale) {
        boolean result = false;

        for (Detail bid : flaggable.getBids().getDetails()) {
            for (Award award : flaggable.getAwards()) {
                if (!Award.Status.active.equals(award.getStatus()) || bid.getValue() == null
                        || bid.getValue().getAmount() == null || award.getValue() == null || award.getValue()
                        .getAmount() == null || !award.getValue().getCurrency().equals(bid.getValue().getCurrency())
                        || award.getValue().getAmount().equals(bid.getValue().getAmount())) {
                    continue;
                }
                BigDecimal dLeft = relativeDistanceLeft(bid.getValue().getAmount(), award.getValue().getAmount()).
                        multiply(GenericOCDSController.ONE_HUNDRED);

                BigDecimal dRight = relativeDistanceRight(bid.getValue().getAmount(), award.getValue().getAmount()).
                        multiply(GenericOCDSController.ONE_HUNDRED);


                //using the same logic as owen here...
                if (dLeft.doubleValue() % 1 == 0 || dRight.doubleValue() % 1 == 0) {
                    result = true;
                    rationale.append("Award=").append(award.getValue().getAmount())
                            .append(" with bid=").append(bid.getValue().getAmount()).append("; ");
                    break;
                }

            }
        }
        return result;
    }

}

@Component
public class ReleaseFlagI171Processor extends AbstractFlaggedReleaseFlagProcessor {


    public static final BigDecimal MAX_ALLOWED_PERCENT_TENDER_VALUE_AMOUNT = new BigDecimal(0.01);


    @PostConstruct
    @Override
    protected void setPredicates() {
        preconditionsPredicates = Collections.synchronizedList(Arrays.asList(
                FlaggedReleasePredicates.ACTIVE_AWARD,
                FlaggedReleasePredicates.ELECTRONIC_SUBMISSION,
                FlaggedReleasePredicates.OPEN_PROCUREMENT_METHOD,
                FlaggedReleasePredicates.TENDER_VALUE_AMOUNT
        ));
    }


    @Override
    protected void setFlag(Flag flag, FlaggedRelease flaggable) {
        flaggable.getFlags().setI171(flag);
    }

    @Override
    protected Set<FlagType> flagTypes() {
        return new HashSet<FlagType>(Arrays.asList(FlagType.RIGGING, FlagType.FRAUD));
    }

    @Override
    protected Boolean calculateFlag(FlaggedRelease flaggable, StringBuffer rationale) {

        boolean result = false;
        for (Award award : flaggable.getAwards()) {
            if (!Award.Status.active.equals(award.getStatus())) {
                continue;
            }

            BigDecimal dLeft = relativeDistanceLeft(flaggable.getTender().getValue().getAmount(),
                    award.getValue().getAmount());

            BigDecimal dRight = relativeDistanceRight(flaggable.getTender().getValue().getAmount(),
                    award.getValue().getAmount());

            rationale.append(";Award=").append(award.getValue().getAmount())
                    .append(" with tender=").append(flaggable.getTender().getValue().getAmount());

            if (dLeft.compareTo(MAX_ALLOWED_PERCENT_TENDER_VALUE_AMOUNT) < 0
                    || dRight.compareTo(MAX_ALLOWED_PERCENT_TENDER_VALUE_AMOUNT) < 0) {
                result = true;
                break;
            }

        }
        return result;
    }


}

