public final class FlaggedReleasePredicates {

    private FlaggedReleasePredicates() {

    }

    public static final NamedPredicate<FlaggedRelease> TENDER_START_DATE = new NamedPredicate<>(
            "Needs to have tender start date", p -> p.getTender() != null && p.getTender().getTenderPeriod() != null
            && p.getTender().getTenderPeriod().getStartDate() != null);

    public static final NamedPredicate<FlaggedRelease> TENDER_PROCURING_ENTITY = new NamedPredicate<>(
            "Needs to have tender procuring entity", p -> p.getTender() != null
            && p.getTender().getProcuringEntity() != null);

    public static final NamedPredicate<FlaggedRelease> TENDER_VALUE_AMOUNT = new NamedPredicate<>(
            "Needs to have tender value amount", p -> p.getTender() != null
            && p.getTender().getValue() != null && p.getTender().getValue().getAmount() != null);

    public static final NamedPredicate<FlaggedRelease> TENDER_END_DATE =
            new NamedPredicate<>("Needs to have tender end date", p -> p.getTender() != null
                    && p.getTender().getTenderPeriod() != null && p.getTender().getTenderPeriod().getEndDate() != null);

    public static final NamedPredicate<FlaggedRelease> OPEN_PROCUREMENT_METHOD =
            new NamedPredicate<>("Needs to have open tender procurement method",
                    p -> p.getTender() != null
                            && Tender.ProcurementMethod.open.equals(p.getTender().getProcurementMethod()));

    public static final NamedPredicate<FlaggedRelease> SELECTIVE_PROCUREMENT_METHOD =
            new NamedPredicate<>("Needs to have selective tender procurement method",
                    p -> p.getTender() != null
                            && Tender.ProcurementMethod.selective.equals(p.getTender().getProcurementMethod()));

    public static final NamedPredicate<FlaggedRelease> LIMITED_PROCUREMENT_METHOD =
            new NamedPredicate<>("Needs to have limited tender procurement method",
                    p -> p.getTender() != null
                            && Tender.ProcurementMethod.limited.equals(p.getTender().getProcurementMethod()));

    public static final NamedPredicate<FlaggedRelease> ACTIVE_AWARD_WITH_DATE =
            new NamedPredicate<>("Needs to have at least one active award",
                    p -> p.getAwards().stream().filter(a -> a.getDate() != null
                            && Award.Status.active.equals(a.getStatus())).count() > 0);

    public static final NamedPredicate<FlaggedRelease> ACTIVE_AWARD =
            new NamedPredicate<>("Needs to have at least one active award",
                    p -> p.getAwards().stream().filter(a -> Award.Status.active.equals(a.getStatus())).count() > 0);

    public static final NamedPredicate<FlaggedRelease> AWARDED_AMOUNT =
            new NamedPredicate<>("Needs to have at least one award with awarded amount",
                    p -> p.getAwards().stream().filter(a -> a.getValue() != null
                            && a.getValue().getAmount() != null).count() > 0);

    public static final NamedPredicate<FlaggedRelease> TENDER_ITEMS_CLASSIFICATION =
            new NamedPredicate<>("Needs to have tender with items classification",
                    p -> p.getTender() != null
                            && !p.getTender().getItems().isEmpty()
                            && p.getTender().getItems().stream().findFirst().get().getClassification() != null);

    public static final NamedPredicate<FlaggedRelease> UNSUCCESSFUL_AWARD = new NamedPredicate<>(
            "Needs to have at least one unsuccessful award",
            p -> p.getAwards().stream().filter(a -> Award.Status.unsuccessful.equals(a.getStatus())).count() > 0);

    public static final NamedPredicate<FlaggedRelease> ELECTRONIC_SUBMISSION = new NamedPredicate<>(
            "Needs to have electronic submission tender submission method",
            p -> p.getTender() != null && p.getTender().getSubmissionMethod() != null
                    && p.getTender().getSubmissionMethod().contains(Tender.SubmissionMethod.electronicSubmission));
}

@RestController
public class FrequentSuppliersTimeIntervalController extends GenericOCDSController {

    public static String getFrequentSuppliersResponseKey(FrequentSuppliersResponse response) {
        return getFrequentSuppliersResponseKey(response.getIdentifier().getProcuringEntityId(),
                response.getIdentifier().getSupplierId(), response.getIdentifier().getTimeInterval());
    }

    public static String getFrequentSuppliersResponseKey(String procuringEntityId, String supplierId, Integer
            timeInterval) {
        return new StringBuilder(procuringEntityId).append("-").append(supplierId).append("-").append(timeInterval)
                .toString();
    }

    @ApiOperation(value = "Returns the frequent suppliers of a procuringEntity split by a time interval. "
            + "The time interval is "
            + "a parameter and represents the number of days to take as interval, starting with today and going back "
            + "till the last award date. The awards are grouped by procuringEntity, supplier and the time interval. "
            + "maxAwards parameter is used to designate what is the maximum number of awards granted to one supplier "
            + "by the same procuringEntity inside one timeInterval. The default value for maxAwards is 3 (days) and the"
            + " default value for intervalDays is 365.")
    @RequestMapping(value = "/api/frequentSuppliersTimeInterval", method = {RequestMethod.POST, RequestMethod.GET},
            produces = "application/json")
    public List<FrequentSuppliersResponse> frequentSuppliersTimeInterval(
            @RequestParam(defaultValue = "365", required = false) Integer intervalDays,
            @RequestParam(defaultValue = "3", required = false) Integer maxAwards,
            @RequestParam(required = false) Date now
    ) {

        if (now == null) {
            now = new Date();
        }
        DBObject project = new BasicDBObject();
        project.put("tender.procuringEntity._id", 1);
        project.put("awards.suppliers._id", 1);
        project.put("awards.date", 1);
        project.put(Fields.UNDERSCORE_ID, 0);
        project.put("timeInterval", new BasicDBObject("$ceil", new BasicDBObject("$divide",
                Arrays.asList(new BasicDBObject("$divide", Arrays.asList(new BasicDBObject("$subtract",
                        Arrays.asList(now, "$awards.date")), DAY_MS)), intervalDays))));

        Aggregation agg = Aggregation.newAggregation(
                match(where("tender.procuringEntity").exists(true).and("awards.suppliers.0").exists(true)
                        .and("awards.date").exists(true)),
                unwind("awards"),
                unwind("awards.suppliers"),
                new CustomProjectionOperation(project),
                group(Fields.from(Fields.field("procuringEntityId", "tender.procuringEntity._id"),
                        Fields.field("supplierId", "awards.suppliers._id"),
                        Fields.field("timeInterval", "timeInterval")
                )).
                        count().as("count"),
                project("count").and("identifier").previousOperation(),
                match(where("count").gt(maxAwards)),
                sort(Sort.Direction.DESC, "count")
        );

        AggregationResults<FrequentSuppliersResponse> results = mongoTemplate.aggregate(agg, "release",
                FrequentSuppliersResponse.class);
        List<FrequentSuppliersResponse> list = results.getMappedResults();
        return list;
    }

    public static class FrequentSuppliersId {

        private String procuringEntityId;
        private String supplierId;
        private Integer timeInterval;

        public String getProcuringEntityId() {
            return procuringEntityId;
        }

        public void setProcuringEntityId(String procuringEntityId) {
            this.procuringEntityId = procuringEntityId;
        }

        public String getSupplierId() {
            return supplierId;
        }

        public void setSupplierId(String supplierId) {
            this.supplierId = supplierId;
        }

        public Integer getTimeInterval() {
            return timeInterval;
        }

        public void setTimeInterval(Integer timeInterval) {
            this.timeInterval = timeInterval;
        }

        @Override
        public String toString() {
            return "procuringEntityId=" + procuringEntityId + "; supplierId=" + supplierId
                    + "; timeInterval=" + timeInterval;
        }
    }

    public static class FrequentSuppliersResponse {
        private FrequentSuppliersId identifier;
        private Integer count;

        public FrequentSuppliersId getIdentifier() {
            return identifier;
        }

        public void setIdentifier(FrequentSuppliersId identifier) {
            this.identifier = identifier;
        }

        public Integer getCount() {
            return count;
        }

        public void setCount(Integer count) {
            this.count = count;
        }

        @Override
        public String toString() {
            return identifier.toString() + "; count=" + count;
        }
    }

}

public abstract class GenericOCDSController {

    private static final int LAST_MONTH_ZERO = 11;
    public static final int BIGDECIMAL_SCALE = 15;
    public static final int DAY_MS = 86400000;

    public static final BigDecimal ONE_HUNDRED = new BigDecimal(100);


    protected Map<String, Object> filterProjectMap;

    protected final Logger logger = LoggerFactory.getLogger(GenericOCDSController.class);

    @Autowired
    protected MongoTemplate mongoTemplate;

    /**
     * Gets the date of the first day of the year (01.01.year)
     *
     * @param year
     * @return
     */
    protected Date getStartDate(final int year) {
        Calendar cal = Calendar.getInstance();
        cal.set(Calendar.YEAR, year);
        cal.set(Calendar.DAY_OF_YEAR, 1);
        Date start = cal.getTime();
        return start;
    }

    /**
     * This is used to build the start date filter query when a monthly filter is used.
     *
     * @param year
     * @param month
     * @return
     */
    protected Date getMonthStartDate(final int year, final int month) {
        Calendar cal = Calendar.getInstance();
        cal.set(Calendar.YEAR, year);
        cal.set(Calendar.MONTH, month - 1);
        cal.set(Calendar.DAY_OF_MONTH, 1);
        Date start = cal.getTime();
        return start;
    }

    /**
     * This is used to build the end date filter query when a monthly filter is used.
     *
     * @param year
     * @param month
     * @return
     */
    protected Date getMonthEndDate(final int year, final int month) {
        Calendar cal = Calendar.getInstance();
        cal.set(Calendar.YEAR, year);
        cal.set(Calendar.MONTH, month - 1);
        cal.set(Calendar.DAY_OF_MONTH, cal.getActualMaximum(Calendar.DAY_OF_MONTH));
        Date end = cal.getTime();
        return end;
    }


    /**
     * Gets the date of the last date of the year (31.12.year)
     *
     * @param year
     * @return
     */
    protected Date getEndDate(final int year) {
        Calendar cal = Calendar.getInstance();
        cal.set(Calendar.YEAR, year);
        cal.set(Calendar.MONTH, LAST_MONTH_ZERO);
        cal.set(Calendar.DAY_OF_MONTH, cal.getActualMaximum(Calendar.DAY_OF_MONTH));
        Date end = cal.getTime();
        return end;
    }

    protected String ref(String field) {
        return "$" + field;
    }


    /**
     * Appends the procuring bid type id for this filter, this will fitler based
     * on tender.items.classification._id
     *
     * @param filter
     * @return the {@link Criteria} for this filter
     */
    protected Criteria getBidTypeIdFilterCriteria(final DefaultFilterPagingRequest filter) {
        return createFilterCriteria("tender.items.classification._id", filter.getBidTypeId(), filter);
    }

    /**
     * Adds monthly projection operation, when needed, if the
     * {@link YearFilterPagingRequest#getMonthly()}
     *
     * @param filter
     * @param project
     * @param field
     */
    protected void addYearlyMonthlyProjection(YearFilterPagingRequest filter, DBObject project, String field) {
        project.put("year", new BasicDBObject("$year", field));
        if (filter.getMonthly()) {
            project.put(("month"), new BasicDBObject("$month", field));
        }
    }

    protected CustomSortingOperation getSortByYearMonth(YearFilterPagingRequest filter) {
        DBObject sort = new BasicDBObject();
        if (filter.getMonthly()) {
            sort.put("_id.year", 1);
            sort.put("_id.month", 1);
        } else {
            sort.put("year", 1);
        }
        return new CustomSortingOperation(sort);
    }

    /**
     * Similar to {@link #getSortByYearMonth(YearFilterPagingRequest)} but it can be used
     * if additional grouping elements are present, besides month and year
     *
     * @param filter
     * @return
     */
    protected CustomSortingOperation getSortByYearMonthWhenOtherGroups(YearFilterPagingRequest filter,
                                                                       String... otherSort) {
        DBObject sort = new BasicDBObject();
        if (filter.getMonthly()) {
            sort.put("_id.year", 1);
            sort.put("_id.month", 1);
        } else {
            sort.put("_id.year", 1);
        }
        if (otherSort != null) {
            Arrays.asList(otherSort).forEach(s -> sort.put(s, 1));
        }
        return new CustomSortingOperation(sort);
    }


    protected void addYearlyMonthlyReferenceToGroup(YearFilterPagingRequest filter, DBObject group) {
        if (filter.getMonthly()) {
            group.put(Fields.UNDERSCORE_ID, new BasicDBObject("year", "$year").append("month", "$month"));
        } else {
            group.put(Fields.UNDERSCORE_ID, "$year");
        }
    }

    /**
     * Returns the grouping fields based on the {@link YearFilterPagingRequest#getMonthly()} setting
     *
     * @param filter
     * @return
     */
    protected String[] getYearlyMonthlyGroupingFields(YearFilterPagingRequest filter) {
        if (filter.getMonthly()) {
            return new String[]{"$year", "$month"};
        } else {
            return new String[]{"$year"};
        }
    }

    /**
