    private <S> Criteria createFilterCriteria(final String filterName, final Set<S> filterValues,
                                              final DefaultFilterPagingRequest filter) {
        if (filterValues == null) {
            return new Criteria();
        }
        return where(filterName).in(filterValues.toArray());
    }

